package com.orderflow.scheduler;
import io.micrometer.core.instrument.Gauge;import io.micrometer.core.instrument.MeterRegistry;import java.time.Duration;import org.springframework.jdbc.core.JdbcTemplate;
public class OutboxReliabilityMetrics{private static final org.slf4j.Logger LOGGER=org.slf4j.LoggerFactory.getLogger(OutboxReliabilityMetrics.class);public OutboxReliabilityMetrics(JdbcTemplate jdbc,MeterRegistry registry,String service,OutboxMetricsProperties properties){gauge(registry,"outbox_backlog",service,()->count(jdbc,"SELECT count(*) FROM outbox_event WHERE status IN('NEW','IN_PROGRESS')"));gauge(registry,"outbox_stale_in_progress",service,()->count(jdbc,"SELECT count(*) FROM outbox_event WHERE status='IN_PROGRESS' AND locked_at < CURRENT_TIMESTAMP - (? * interval '1 millisecond')",properties.lockTimeout().toMillis()));gauge(registry,"outbox_failed",service,()->count(jdbc,"SELECT count(*) FROM outbox_event WHERE status='FAILED'"));gauge(registry,"outbox_oldest_unpublished_age_seconds",service,()->decimal(jdbc,"SELECT COALESCE(EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-min(created_at))),0) FROM outbox_event WHERE status IN('NEW','IN_PROGRESS')"));}private void gauge(MeterRegistry registry,String name,String service,java.util.function.DoubleSupplier value){Gauge.builder(name,value,java.util.function.DoubleSupplier::getAsDouble).tag("service",service).strongReference(true).register(registry);}private double count(JdbcTemplate jdbc,String sql,Object...args){try{Long value=jdbc.queryForObject(sql,Long.class,args);return value==null?0:value;}catch(RuntimeException exception){LOGGER.debug("Unable to read outbox metric",exception);return 0;}}private double decimal(JdbcTemplate jdbc,String sql){try{Number value=jdbc.queryForObject(sql,Number.class);return value==null?0:value.doubleValue();}catch(RuntimeException exception){LOGGER.debug("Unable to read outbox metric",exception);return 0;}}}
